TN.defSec("analgesia-sedation",{"acute-pain":{"id":"acute-pain","variants":[{"id":"pain-mild-moderate","o":{"N":[{"t":"Heat or cold, immobilization and elevation of the injured extremity"}],"T":[{"t":"Acetaminophen 650 to 1000 mg PO (children 15 mg/kg PO or PR)"},{"t":"Ibuprofen 400 to 800 mg PO (children 10 mg/kg PO)","if":"alternatively","fl":[{"k":"renal","v":"GI irritation, renal dysfunction, platelet dysfunction; increases the risk of cardiac death in ischemic heart disease; avoid aspirin in children (Reye syndrome)"}]}]},"name":"Mild to moderate pain","level":"III","imp":"Acute pain, mild to moderate","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با درد مچ پا بعد از پیچ‌خوردگی، درد 4 از 10، علائم حیاتی طبیعی.","why":"درد خفیف تا متوسط با داروی غیراپیوئیدی خوراکی درمان می‌شود."},{"id":"pain-moderate-severe","o":{"T":[{"t":"Morphine 0.1 mg/kg IV (children 0.1 to 0.2 mg/kg IV)","fl":[{"k":"hi","v":""}]},{"t":"Fentanyl 1 μg/kg IV (children 1 to 2 μg/kg)","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Hydromorphone 0.2 to 1 mg IV (children 0.01 mg IV)","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Titrate the doses to effect; watch for respiratory depression, nausea and vomiting, confusion, pruritus and urinary retention"},{"t":"Oral opioids may be tried as an alternative (variable absorption, slower effect); caution with codeine (unreliable analgesic) and tramadol (CNS toxicity)"}]},"name":"Moderate to severe pain","level":"II","imp":"Acute pain, moderate to severe","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۵۰ ساله با درد شدید پهلو (۹ از ۱۰) و استفراغ؛ علائم حیاتی پایدار.","why":"اپیوئید داروی انتخابی در درد متوسط تا شدید است؛ تیتراسیون تا اثر و پایش تنفس."}],"ch":"7","name":"Acute pain","name_fa":"درد حاد","cc":["joint-limb-pain","abdominal-pain","back-neck-pain"],"keywords":"analgesia, acetaminophen, ibuprofen, morphine, fentanyl, hydromorphone, opioid, NSAID, codeine, tramadol, oligoanalgesia, مسکن","status":"draft","features":["درد حاد شکایت اصلی ۷۵ تا ۸۰٪ مراجعات اورژانس است","پاسخ‌های فیزیولوژیک (ضربان، فشار، تنفس، رفتار) ارتباط ضعیفی با شدت درد دارند؛ از مقیاس‌های معتبر درد استفاده کن (در سالمندان و تروما کمتر دقیق؛ در کودکان کوچک ستون اصلی)","کودکان در معرض oligoanalgesia‌اند (دشواری ارزیابی، ناآشنایی با دوزها)","انتخاب دارو بر اساس شدت درد، راه تجویز و مدت اثر مطلوب"],"ddx":[{"n":"Pain heralding a life- or limb-threatening condition","cm":1,"note":"درد حاد را همیشه علت‌یابی کن"},{"n":"Mild to moderate pain |"},{"n":"Moderate to severe pain |"}],"redflags":["درد شدید همراه ناپایداری همودینامیک یا نشانه‌های اورژانس زمینه‌ای"],"guide":"# منطق\n- غیردارویی: گرما/سرما، بی‌حرکتی و بالا نگه داشتن اندام، حواس‌پرتی؛ ساکارز خوراکی در شیرخواران.\n- خفیف تا متوسط: استامینوفن یا NSAID (تزریقی از خوراکی مؤثرتر نیست).\n- متوسط تا شدید: اپیوئید وریدی تیتره تا اثر.\n- هرگز آسپرین در کودکان (سندرم Reye)؛ NSAID در بیماری ایسکمیک قلب خطر مرگ قلبی را بالا می‌برد.\n- کدئین قابل‌اعتماد نیست (تا ۱۰٪ آمریکایی‌ها آنزیم لازم را ندارند)؛ ترامادول می‌تواند سمیت CNS بدهد.","pearls":["کودکان به نسبت وزن به اپیوئید بیشتری نیاز دارند."],"section":"analgesia-sedation","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 7: Acute Pain Management and Procedural Sedation, pp. 67–76"},"procedural-sedation":{"id":"procedural-sedation","variants":[{"id":"psa-adult-minimal","o":{"N":[{"t":"Continuous cardiac monitor with pulse oximetry, oxygen, suction, resuscitation equipment; informed consent; constant observation by a provider trained in airway management; monitor BP, HR, RR and level of consciousness (capnography advocated)"}],"T":[{"t":"Midazolam 0.05 to 0.1 mg/kg IV, may repeat 0.05 mg/kg every 2 min until adequately sedated (IM 0.1 mg/kg)","fl":[{"k":"hi","v":""}]},{"t":"Fentanyl 1 to 3 μg/kg IV, can be titrated up to 5 μg/kg","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Nitrous oxide 50:50 mixture with oxygen, inhaled","if":"alternatively","fl":[{"k":"ci","v":"pregnancy, pneumothorax, pneumocephalus, vascular air embolus"}]},{"t":"Supplemental oxygen"}]},"name":"Adult minimal sedation","level":"III","imp":"Procedural sedation, minimal (adult)","cond":"Urgent","act":"RBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۴۰ ساله نیازمند آرام‌بخشی خفیف برای ترمیم زخم دردناک.","why":"حداقل آرام‌بخشی با میدازولام، فنتانیل یا نیتروس اکساید."},{"id":"psa-adult-moderate-deep","o":{"N":[{"t":"Continuous cardiac monitor with pulse oximetry, oxygen, suction, resuscitation equipment; informed consent; constant observation by a provider trained in airway management; capnography"}],"T":[{"t":"Fentanyl 1 to 2 μg/kg IV plus Midazolam 0.1 mg/kg IV (moderate and deep sedation)","fl":[{"k":"hi","v":""}]},{"t":"Propofol 0.5 to 1.0 mg/kg IV, followed by 0.5 mg/kg every 3 min if needed","if":"alternatively","fl":[{"k":"hi","v":""},{"k":"ci","v":"allergy to eggs or soy products; correct hypovolemia first"}]},{"t":"Etomidate 0.15 mg/kg IV, followed by 0.1 mg/kg every 2 min if needed","if":"alternatively","fl":[{"k":"note","v":"temporary adrenal insufficiency; up to 20% myoclonic jerking"}]},{"t":"Ketamine 1 mg/kg IV (or 2 to 5 mg/kg IM) for dissociative sedation","if":"alternatively","fl":[{"k":"hi","v":""},{"k":"ci","v":"children under 3 months, increased intraocular pressure, obstructive hydrocephalus"}]},{"t":"Ketamine 0.125 to 0.5 mg/kg plus Propofol 0.5 mg/kg IV (\"ketofol\")","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Methohexital 1 mg/kg IV","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Pentobarbital 2.5 mg/kg IV followed by 1.25 mg/kg as needed up to two times, IV rate < 50 mg/min","if":"alternatively, minimal and moderate sedation, often for radiologic procedures","fl":[{"k":"hi","v":""}]},{"t":"Lidocaine 0.05 mg/kg IV","if":"propofol injection pain"},{"t":"Pretreatment with ondansetron; [emergence reaction] Midazolam 0.1 mg/kg IM or IV","if":"ketamine vomiting"},{"t":"Flumazenil","if":"benzodiazepine reversal; not routine"}]},"name":"Adult moderate or deep sedation","level":"II","imp":"Procedural sedation, moderate or deep (adult)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۵ ساله نیازمند جا‌اندازی دررفتگی شانه با آرام‌بخشی متوسط تا عمیق.","why":"آرام‌بخشی متوسط یا عمیق با داروهای تیتره؛ پایش مداوم و آمادگی راه هوایی."},{"id":"psa-elderly","o":{"T":[{"t":"Etomidate (good choice, minimal cardiovascular effects) 0.15 mg/kg IV, followed by 0.1 mg/kg every 2 min if needed"},{"t":"initial and subsequent doses 50% of those recommended for younger adults","if":"propofol is used"}]},"name":"Elderly","level":"II","imp":"Procedural sedation in the elderly","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۸۲ ساله با شکستگی هیپ نیازمند آرام‌بخشی برای پروسیجر.","why":"عوارض بیشتر و خطر تضعیف تنفس با همه داروها؛ اتومیدیت به‌دلیل اثر قلبی‌عروقی کم انتخاب خوب است."},{"id":"psa-child","o":{"N":[{"t":"Allow parents to stay with the child; age-appropriate distraction; oral sucrose for infants undergoing painful procedures"}],"T":[{"t":"Midazolam IV 0.05 to 0.1 mg/kg (IM 0.05 to 0.1 mg/kg; intranasal 0.2 to 0.4 mg/kg; PO/PR 0.5 mg/kg)","fl":[{"k":"hi","v":""}]},{"t":"Propofol IV 1 to 2 mg/kg, followed by 0.5 mg/kg repeat doses as needed","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Etomidate IV 0.2 to 0.3 mg/kg","if":"alternatively"},{"t":"Ketamine IV 1 to 1.5 mg/kg or IM 4 to 5 mg/kg","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Pentobarbital IV 1 to 2 mg/kg repeated every 3 to 5 min as needed; or Methohexital IV 0.5 to 1 mg/kg","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Fentanyl 1 to 2 μg/kg plus Midazolam 0.05 to 0.1 mg/kg IV","if":"alternatively","fl":[{"k":"hi","v":""}]},{"t":"Propofol 1 mg/kg plus Ketamine 0.5 mg/kg IV","if":"alternatively","fl":[{"k":"hi","v":""}]}]},"name":"Children","level":"II","imp":"Procedural sedation in a child","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: supplemental oxygen during sedation; if SpO2 < 94% nasal cannula or face mask with flow by age and weight","sc":"کودکی ۵ ساله با پارگی صورت که برای ترمیم نیاز به بی‌حرکتی دارد.","why":"والدین کنار کودک بمانند و روش‌های حواس‌پرتی؛ دارو بر اساس وزن و پروسیجر."}],"ch":"7","name":"Procedural sedation and analgesia (PSA)","name_fa":"آرام‌بخشی و بی‌دردی حین پروسیجر","cc":["airway-procedure"],"keywords":"sedation, propofol, ketamine, etomidate, midazolam, fentanyl, nitrous oxide, ketofol, methohexital, pentobarbital, flumazenil, PSA","status":"draft","features":["استفاده از دارو برای ایجاد کاهش سطح هوشیاری با حفظ عملکرد قلبی‌تنفسی تا انجام پروسیجر دردناک یا تصویربرداری","با عمیق‌تر شدن آرام‌بخشی خطر تضعیف تنفس و از دست رفتن باز بودن راه هوایی بیشتر می‌شود","سطوح: حداقل (anxiolysis)، متوسط (conscious sedation) و عمیق","خوردن اخیر منع‌مصرف نیست؛ ۳ ساعت انتظار بعد از آخرین خوردن خطر آسپیراسیون کم دارد","عارضه به عمق آرام‌بخشی و ذخیره فیزیولوژیک بستگی دارد؛ در ذخیره محدود، سالمند، راه هوایی دشوار مشاوره بیهوشی"],"ddx":[{"n":"Patient with limited physiologic reserve (cardiorespiratory disease)","cm":1,"note":"مشاوره بیهوشی"},{"n":"Predicted difficult airway |","cm":1},{"n":"Elderly","note":"افزایش عوارض؛ اتومیدیت انتخاب خوب"},{"n":"Child |"}],"redflags":["ذخیره فیزیولوژیک محدود، راه هوایی دشوار پیش‌بینی‌شده"],"guide":"# آماده‌سازی و نظارت\n- مانیتور قلب با پالس‌اکسی‌متری، اکسیژن، ساکشن، تجهیزات احیای متناسب؛ رضایت آگاهانه؛ مراقب آموزش‌دیده در راه هوایی و ارزیابی پیوسته BP، HR، RR و هوشیاری؛ کاپنوگرافی توصیه می‌شود.\n- داروها به‌صورت بولوس‌های کوچک وریدی با فاصله کافی تا اثر اوج.\n- تضعیف گذرای تنفس معمولاً با بگ‌ماسک اداره می‌شود.\n- ترخیص فقط بعد از بهبود کامل، همراه فرد بالغ، بدون رانندگی ۲۴ ساعت.","pearls":["فنتانیل: سفتی دیواره قفسه سینه (rigid chest) در دوز بالا یا تزریق سریع (تزریق آهسته طی ۳–۵ دقیقه).","کتامین: تهوع در نوجوانان؛ ondansetron پیشگیری می‌کند؛ واکنش emergence با میدازولام 0.1 mg/kg.","پروپوفول: هیپوولمی را قبل از تجویز اصلاح کن؛ آلرژی به تخم‌مرغ یا سویا ممنوع."],"section":"analgesia-sedation","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 7: Acute Pain Management and Procedural Sedation, pp. 67–76"},"local-regional-anesthesia":{"id":"local-regional-anesthesia","variants":[{"id":"la-infiltration","o":{"T":[{"t":"Lidocaine infiltration, maximum dose 4.5 mg/kg without epinephrine or 7 mg/kg with epinephrine; buffer 1 mL NaHCO3 to 9 mL lidocaine immediately before use"},{"t":"Bupivacaine infiltration, maximum dose 2 mg/kg without epinephrine or 3 mg/kg with epinephrine; buffer 1 mL NaHCO3 to 29 mL bupivacaine","if":"prolonged procedure"},{"t":"Draw back the plunger before injection to avoid intravascular injection"},{"t":"LET (lidocaine, epinephrine, tetracaine): saturated cotton ball or gauze for a minimum of 20 to 30 minutes","if":"topical alternative on an open wound","fl":[{"k":"ci","v":"mucous membranes, end-arterial fields"}]},{"t":"EMLA cream (lidocaine and prilocaine), onset 45 to 60 minutes","if":"intact skin for venipuncture and superficial procedures","fl":[{"k":"ci","v":"infants under 3 months (caution), predisposition to methemoglobinemia"}]}]},"name":"Local infiltration","level":"III","imp":"Local anesthesia for wound or procedure","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۸ ساله با پارگی ساده ساعد که برای ترمیم نیاز به بی‌حسی دارد.","why":"ارتشاح مستقیم لیدوکائین؛ رعایت حداکثر دوز."},{"id":"la-digital-block","o":{"N":[{"t":"Assess and document neurovascular status before the procedure"},{"t":"Hand prone (palm down); nerves run on the lateral aspect of the finger dorsal and palmar sides"}],"T":[{"t":"Digital block: insert the needle on the dorsal surface of the proximal phalanx, advance toward the volar surface immediately adjacent to the phalanx, aspirate, inject 1 mL of anesthetic; retract slowly while injecting another 1 mL; direct across the dorsum to the other side and inject 1 mL while withdrawing; repeat on the other side (toes the same way)","fl":[{"k":"note","v":"avoid epinephrine with suspected digital vascular injury"}]},{"t":"Flexor tendon sheath block: hand supine, patient flexes the finger, inject at the distal palmar crease into the flexor tendon sheath, 2 to 3 mL after the \"pop\" (may not anesthetize the distal fingertip)","if":"alternative one-injection"}]},"name":"Digital block (finger or toe)","level":"III","imp":"Digital nerve block","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با له‌شدگی نوک انگشت که نیاز به بی‌حسی انگشت دارد.","why":"بلوک دیجیتال به بیهوشی بهتر با دوز کمتر و بدون اعوجاج بافت می‌انجامد؛ شروع کندتر."},{"id":"la-intercostal-block","o":{"N":[{"t":"Patient sits upright, ipsilateral arm raised on the head; site: mid-axillary line of the affected rib or the \"rib angle\" (about 6 cm posterior to the mid-axillary line, preferred)"},{"t":"Monitor for respiratory symptoms for 30 minutes after the procedure (pneumothorax in up to 9%)"}],"T":[{"t":"Intercostal block: palpate the inferior border of the rib, retract skin cephalad, raise a wheal, insert needle bevel up toward the lower aspect of the bone at about 10 degrees off perpendicular, march the needle caudally off the bone, aspirate, inject 2 to 5 mL of anesthetic"}]},"name":"Intercostal nerve block","level":"III","imp":"Intercostal nerve block (rib fracture or chest tube)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۶۰ ساله با شکستگی دنده و درد شدید هنگام تنفس.","why":"بلوک بین‌دنده‌ای درد دنده را کم می‌کند؛ خطر پنوموتوراکس تا ۹٪ و پایش ۳۰ دقیقه."},{"id":"la-femoral-block","o":{"N":[{"t":"Patient supine, inguinal crease exposed; femoral nerve about 1 cm lateral to the femoral artery"},{"t":"Assess and document distal neurovascular status"}],"T":[{"t":"Femoral nerve block (ultrasound guidance recommended): raise a wheal, direct the needle toward the nerve (anterior thigh paresthesia confirms position; otherwise direct more laterally), retract slightly and inject approximately 20 mL of anesthetic into the perineural space"},{"t":"Firm pressure distal to the injection site for 5 minutes to promote cephalad distribution","if":"three-in-one block (femoral, obturator, lateral femoral cutaneous)"}]},"name":"Femoral nerve block (and three-in-one)","level":"III","imp":"Femoral nerve block (femur or hip fracture)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۸۵ ساله با شکستگی گردن فمور و درد شدید.","why":"بلوک عصب فمورال برای شکستگی‌های پروگزیمال فمور و هیپ؛ سونوگرافی توصیه می‌شود."},{"id":"la-hematoma-block","o":{"T":[{"t":"Hematoma block (sterile approach): direct the needle to the fracture site, aspiration of blood confirms the hematoma, inject 5 to 15 mL of anesthetic; do not exceed the maximum dose"}]},"name":"Hematoma block","level":"III","imp":"Hematoma block for fracture reduction","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زنی ۴۵ ساله با شکستگی دیستال رادیوس که نیاز به جا‌اندازی دارد.","why":"تزریق بی‌حسی به هماتوم شکستگی برای کمک به جا‌اندازی."}],"ch":"7","name":"Local, topical and regional anesthesia","name_fa":"بی‌حسی موضعی، سطحی و ناحیه‌ای","cc":["wound-bite","airway-procedure"],"keywords":"lidocaine, bupivacaine, digital block, femoral nerve block, intercostal block, hematoma block, LET, EMLA, local anesthetic toxicity, بی‌حسی","status":"draft","features":["سمیت داروی بی‌حسی به دوز کل و سرعت افزایش غلظت پلاسما بستگی دارد؛ در هیپوکسی، هیپرکاربی و اسیدوز بیشتر است","سمیت: علائم CNS تا کما و علائم قلبی‌عروقی تا کلاپس","آلرژی به LA نادر است و معمولاً به نگهدارنده؛ از داروی بدون نگهدارنده از گروه دیگر یا دیفن‌هیدرامین/بنزیل الکل استفاده کن","درد تزریق را کم کن: تزریق آهسته با سوزن 27 یا 30، از لبه زخم، محلول گرم و بافر شده با بیکربنات","اپی‌نفرین (1:100,000) مدت اثر را زیاد می‌کند و هموستاز می‌دهد؛ در شک به آسیب عروقی انگشت یا بیماری عروق محیطی پرهیز"],"ddx":[{"n":"Local anesthetic systemic toxicity |","cm":1},{"n":"Allergy to LA (usually the preservative) |"},{"n":"Intravascular injection |"}],"redflags":["ماکزیمم دوز را رعایت کن؛ قبل از تزریق پیستون را عقب بکش"],"guide":"لیدوکائین شایع‌ترین LA در اورژانس (شروع 2–5 دقیقه، مدت 1–2 ساعت). بوپیواکائین برای پروسیجرهای طولانی (شروع 3–7 دقیقه، مدت 90 دقیقه تا 6 ساعت). بلوک‌های ناحیه‌ای برای زخم‌های پیچیده، شکستگی و دررفتگی؛ قبل از بلوک وضعیت عصبی‌عروقی دیستال را بررسی و ثبت کن.","section":"analgesia-sedation","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 7: Acute Pain Management and Procedural Sedation, pp. 67–76"},"chronic-pain-syndromes":{"id":"chronic-pain-syndromes","variants":[{"id":"cps-transformed-migraine","o":{"T":[{"t":"Stop prior medications (primary treatment)"},{"t":"Celecoxib or prednisone taper","if":"secondary"}]},"name":"Transformed migraine","level":"III","imp":"Transformed migraine","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۸ ساله با سردرد روزانه ثابت و کند که ابتدا میگرنی بوده، همراه تهوع.","why":"اساس درمان: قطع داروهای قبلی؛ درمان ثانویه سلکوکسیب یا پردنیزون تاپر."},{"id":"cps-fibromyalgia","o":{"T":[{"t":"Duloxetine 30 mg PO daily to start (primary)"},{"t":"Pregabalin 50 mg three times daily to start","if":"secondary"}]},"name":"Fibromyalgia","level":"III","imp":"Fibromyalgia","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۴۵ ساله با درد منتشر عضلانی، خستگی و اختلال خواب؛ بیش از 11 نقطه ماشه دردناک.","why":"درمان اولیه دولوکستین و ثانویه پره‌گابالین."},{"id":"cps-back-neck","o":{"T":[{"t":"Duloxetine 30 mg PO daily to start (primary)"},{"t":"Amitriptyline 25 mg/d PO to start","if":"secondary"}]},"name":"Chronic back or neck pain","level":"III","imp":"Chronic back or neck pain","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۰ ساله با کمردرد مزمن بدون علائم عصبی جدید.","why":"دولوکستین درمان اولیه و آمی‌تریپتیلین ثانویه."},{"id":"cps-poststroke","o":{"T":[{"t":"Pregabalin 50 mg three times daily to start (primary)"},{"t":"Gabapentin 300 mg daily, increase up to a maximum of 1200 mg three times daily according to response","if":"secondary"}]},"name":"Poststroke pain","level":"III","imp":"Poststroke pain","cond":"Urgent","act":"RBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۶۸ ساله با درد سوزشی سمت ضعیف‌شده بعد از سکته مغزی و آلودینیا.","why":"پره‌گابالین اولیه و گاباپنتین ثانویه."},{"id":"cps-hiv-neuropathy","o":{"T":[{"t":"Optimize antiretroviral therapy (primary)"},{"t":"Lamotrigine 25 mg daily to start","if":"secondary"}]},"name":"HIV-associated sensory neuropathy","level":"III","imp":"HIV-associated sensory neuropathy","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۰ ساله مبتلا به HIV با درد و پارستزی متقارن در پاها.","why":"بهینه‌سازی درمان ضد رتروویروس و ثانویه لاموتریژین."},{"id":"cps-crps","o":{"T":[{"t":"Prednisone taper (primary)","if":"acute","fl":[{"k":"note","v":"dose not given in the book"}]},{"t":"Ketamine by specialist","if":"secondary"}]},"name":"Complex regional pain syndrome types I and II","level":"III","imp":"Complex regional pain syndrome","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۵۰ ساله سه هفته بعد از شکستگی مچ با درد سوزشی، آلودینیا، ادم و تعریق موضعی.","why":"در مرحله حاد پردنیزون تاپر؛ کتامین توسط متخصص."},{"id":"cps-postherpetic","o":{"T":[{"t":"Pregabalin 50 mg three times daily to start, or Gabapentin 300 mg daily increased up to a maximum of 1200 mg three times daily (primary)"},{"t":"Amitriptyline 25 mg/d PO to start","if":"secondary"}]},"name":"Postherpetic neuralgia","level":"III","imp":"Postherpetic neuralgia","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۷۰ ساله پس از زونا با درد تیرکشنده و آلودینیا در همان درماتوم.","why":"پره‌گابالین یا گاباپنتین اولیه و آمی‌تریپتیلین ثانویه."},{"id":"cps-diabetic-neuropathy","o":{"L":[{"t":"Blood sugar"}],"T":[{"t":"Duloxetine 30 mg PO daily to start (primary)"},{"t":"Pregabalin 50 mg three times daily to start, or Gabapentin 300 mg daily increased up to a maximum of 1200 mg three times daily","if":"secondary"}]},"name":"Painful diabetic neuropathy","level":"III","imp":"Painful diabetic neuropathy","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۰ ساله دیابتی با بی‌حسی متقارن و درد سوزشی/چاقویی پاها.","why":"دولوکستین اولیه و پره‌گابالین یا گاباپنتین ثانویه."},{"id":"cps-phantom-limb","o":{"T":[{"t":"Gabapentin 300 mg daily, increase up to a maximum of 1200 mg three times daily according to response (primary)"},{"t":"Amitriptyline 25 mg/d PO to start","if":"secondary"}]},"name":"Phantom limb pain","level":"III","imp":"Phantom limb pain","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۵ ساله با قطع پا و درد ساق «پای از دست رفته».","why":"گاباپنتین اولیه و آمی‌تریپتیلین ثانویه."}],"ch":"8","name":"Chronic pain syndromes","name_fa":"سندرم‌های درد مزمن","cc":["back-neck-pain","headache","joint-limb-pain"],"keywords":"chronic pain, fibromyalgia, CRPS, complex regional pain, postherpetic neuralgia, diabetic neuropathy, phantom limb, transformed migraine, duloxetine, pregabalin, gabapentin, amitriptyline, lamotrigine","status":"draft","features":["درد مزمن: بیش از ۳ ماه یا ماندن بیش از زمان معمول بهبود آسیب (یا ۱ ماه بعد از سیر معمول بیماری حاد)؛ هدف کاهش درد و بازگشت عملکرد است نه حذف کامل","مهم‌ترین کار پزشک اورژانس: تشخیص درد مزمن از درد حادی که نشانه بیماری تهدیدکننده جان یا عضو است","CRPS نوع I (RSD) و II (کازالژی): ۲ هفته یا بیشتر بعد از آسیب؛ آلودینیا و درد سوزشی/تیرکشنده؛ نشانه‌های اولیه ادم، گرمی و تعریق موضعی","درد آسیب حاد (حتی شکستگی) به‌ندرت بیش از ۲ هفته ادامه دارد؛ درد بعد از آن شک به آسیب عصبی را بالا می‌برد","تشخیص قطعی دشوار است و ارجاع به پزشک اصلی و متخصص لازم است"],"ddx":[{"n":"Acute pain heralding a life- or limb-threatening condition |","cm":1},{"n":"Complex regional pain syndrome (post-nerve injury) |","cm":1},{"n":"Fibromyalgia |"},{"n":"Postherpetic neuralgia |"},{"n":"Painful diabetic neuropathy |"},{"n":"Phantom limb pain |"}],"redflags":["علامت یا نشانه غیرمنتظره در بیمار مبتلا به درد مزمن"],"guide":"- اپیوئید برای درمان اولیه درد مزمن در اورژانس توصیه نمی‌شود؛ اگر بیمار نسخه گم‌شده یا دزدیده‌شده می‌گوید به پزشک درد یا پزشک اصلی ارجاع شود و نسخه تکرار نشود.\n- به‌دلیل نیاز به درمان طولانی ایمنی NSAID محدود است.\n- دوزهای شروع: آمی‌تریپتیلین 25 mg/d PO؛ گاباپنتین 300 mg روزانه تا حداکثر 1200 mg سه بار در روز؛ پره‌گابالین 50 mg سه بار در روز؛ دولوکستین 30 mg PO روزانه؛ لاموتریژین 25 mg روزانه.\n- ارجاع به متخصص یکی از مؤثرترین اقدامات است (بهینه‌سازی دارو، تزریق نقطه ماشه، تمرین، فیزیوتراپی، تزریق اپیدورال، بلوک عصب).","section":"analgesia-sedation","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 8: Chronic Pain, pp. 77–80"},"aberrant-drug-behavior":{"id":"aberrant-drug-behavior","variants":[{"id":"aberrant-main","o":{"T":[{"t":"Refuse the controlled substance"},{"t":"Consider the need for alternative medication or treatment"},{"t":"Consider referral for drug counseling"}]},"name":"Aberrant drug-related behavior","level":"III","imp":"Aberrant drug-related behavior","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با ادعای سنگ کلیه و هماتوری، نسخه «گم‌شده» و درخواست اپیوئید؛ در پرونده مراجعات مکرر.","why":"بعد از رد علل واقعی، داروی کنترل‌شده داده نمی‌شود و درمان جایگزین و ارجاع انجام می‌شود."}],"ch":"8","name":"Aberrant drug-related behavior (drug-seeking)","name_fa":"رفتارهای نابجای مرتبط با دارو","cc":["back-neck-pain","headache","joint-limb-pain"],"keywords":"drug seeking, opioid seeking, lost prescription, forged prescription, controlled drug database","status":"draft","features":["طیف از بیماران درد مزمن وابسته به مخدر تا کسانی که دارو برای فروش می‌گیرند؛ شرح حال ممکن است واقعی یا ساختگی باشد","شایع‌ترین شکایات در یک مطالعه اورژانس: کمردرد، سردرد، درد اندام و دندان","روش‌ها: نسخه «گم‌شده»، نامه پزشک، جراحی «قریب‌الوقوع»، هماتوری ساختگی با ادعای سنگ کلیه، خودآزاری، آسیب ساختگی","رفتارهای پیش‌بینی‌کننده: جعل یا تغییر نسخه، فروش دارو، استفاده از نام مستعار، مصرف فعلی مواد غیرمجاز، بیماری ساختگی، پنهان‌کردن مراجعات یا پزشکان متعدد، پرخاشگری هنگام امتناع","تشخیص ممکن است در اورژانس ممکن نباشد؛ پرونده پزشکی و پایگاه داروهای کنترل‌شده کمک می‌کند"],"ddx":[{"n":"Genuine pain from a serious condition","cm":1,"note":"اول علل واقعی را رد کن"},{"n":"Chronic pain with opioid dependence |"},{"n":"Diversion (selling prescriptions) |"}],"redflags":["رفتارهای پیش‌بینی‌کننده غیرقانونی (جعل نسخه، فروش دارو)"],"guide":"درمان: امتناع از دادن داروی کنترل‌شده، در نظر گرفتن داروی یا درمان جایگزین و ارجاع به مشاوره ترک.","section":"analgesia-sedation","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 8: Chronic Pain, pp. 77–80"}});
